2	import { useRouter } from "expo-router";
3	import { useState } from "react";
4	import {
5	  ActivityIndicator,
6	  FlatList,
7	  Pressable,
8	  RefreshControl,
9	  StyleSheet,
10	  View,
11	} from "react-native";
12	import { useSafeAreaInsets } from "react-native-safe-area-context";
13	
14	import { falhaParaTela } from "../api/FalhaDaApi";
15	import { useEu } from "../api/useEu";
16	import { Icon } from "../components/Icon";
17	import { EmptyState, ErrorState } from "../components/StateMessage";
18	import { Logo } from "../marca/Logo";
19	import { Sininho } from "../notificacoes/Sininho";
20	import { useTheme } from "../theme/ThemeProvider";
21	import { espacamento, tamanhos } from "../theme/tokens";
22	import { useFeed } from "./api";
23	import { CartaoDePost } from "./CartaoDePost";
24	
25	// A Home (produto.md 6.2 e prancheta do feed): o logo, o "+" do novo post e o sininho das
26	// notificações (passo 10) no topo, e os posts de quem a pessoa segue intercalados com
27	// recomendações, rolando sem fim.
28	export function FeedScreen() {
29	  const { colors } = useTheme();
30	  const insets = useSafeAreaInsets();
31	  const router = useRouter();
32	  const queryClient = useQueryClient();
33	  const eu = useEu();
34	  const feed = useFeed();
35	  const [atualizando, setAtualizando] = useState(false);
36	
37	  const ehAluno = eu.data?.papeis.includes("aluno") ?? false;
38	  const posts = feed.data?.pages.flatMap((pagina) => pagina.itens) ?? [];
39	
40	  // Puxar para atualizar começa uma sessão nova: outra semente, outra ordem de recomendações.
41	  const atualizar = async () => {
42	    setAtualizando(true);
43	    try {
44	      await queryClient.resetQueries({ queryKey: ["feed"] });
45	    } finally {
46	      setAtualizando(false);
47	    }
48	  };
49	
50	  const cabecalho = (
51	    <View style={styles.topo}>
52	      <Logo largura={110} />
53	      <View style={styles.acoes}>
54	        {ehAluno && (
55	          <Pressable
56	            role="button"
57	            accessibilityLabel="Novo post"
58	            hitSlop={8}
59	            onPress={() => router.push("/novo-post")}
60	            style={styles.botao}
61	          >
62	            <Icon name="novo" color={colors.ink} size={tamanhos.iconeNav} />
63	          </Pressable>
64	        )}
65	        <Sininho />
66	      </View>
67	    </View>
68	  );
69	
70	  return (
71	    <View
72	      style={[
73	        styles.fill,
74	        { paddingTop: insets.top, backgroundColor: colors.bg },
75	      ]}
76	    >
77	      <FlatList
78	        testID="feed"
79	        data={posts}
80	        keyExtractor={(post) => post.id}
81	        renderItem={({ item }) => (
82	          <CartaoDePost
83	            post={item}
84	            leitor={eu.data}
85	            onRemovido={() =>
86	              void queryClient.invalidateQueries({ queryKey: ["feed"] })
87	            }
88	          />
89	        )}
90	        ListHeaderComponent={cabecalho}
91	        ListEmptyComponent={
92	          feed.isPending ? (
93	            <ActivityIndicator style={styles.espera} color={colors.ink2} />
94	          ) : feed.isError ? (
95	            <View style={styles.estado}>
96	              <ErrorState
97	                message={falhaParaTela(feed.error).mensagem}
98	                onRetry={() => void feed.refetch()}
99	              />
100	            </View>
101	          ) : (
102	            <View style={styles.estado}>
103	              <EmptyState
104	                icon="home"
105	                title="Nenhum post ainda."
106	                message="Quando alguém publicar, o post aparece aqui."
107	                action={
108	                  ehAluno
109	                    ? {
110	                        label: "Novo post",
111	                        onPress: () => router.push("/novo-post"),
112	                      }
113	                    : undefined
114	                }
115	              />
116	            </View>
117	          )
118	        }
119	        ListFooterComponent={
120	          <View style={styles.rodape}>
121	            {feed.isFetchingNextPage && (
122	              <ActivityIndicator color={colors.ink2} />
123	            )}
124	            {feed.isError && posts.length > 0 && (
125	              <ErrorState
126	                message={falhaParaTela(feed.error).mensagem}
127	                onRetry={() => void feed.fetchNextPage()}
128	              />
129	            )}
130	          </View>
131	        }
132	        onEndReachedThreshold={0.5}
133	        onEndReached={() => {
134	          if (feed.hasNextPage && !feed.isFetchingNextPage && !feed.isError) {
135	            void feed.fetchNextPage();
136	          }
137	        }}
138	        refreshControl={
139	          <RefreshControl
140	            refreshing={atualizando}
141	            onRefresh={() => void atualizar()}
142	            tintColor={colors.ink2}
143	          />
144	        }
145	      />
146	    </View>
147	  );
148	}
149	
