47	      </Pressable>
48	    );
49	  }
50	
51	  return (
52	    <View
53	      testID={`aviso-${aviso.id}`}
54	      style={[styles.cartao, { backgroundColor: colors.surface }]}
55	    >
56	      <View style={styles.topo}>
57	        <View style={styles.escopo}>
58	          {!aviso.lido && (
59	            <View
60	              testID="bolinha-nao-lido"
61	              style={[styles.bolinha, { backgroundColor: colors.gold }]}
62	            />
63	          )}
64	          <Text
65	            numberOfLines={1}
66	            style={[textStyles.rotulo, styles.rotulo, { color: colors.ink2 }]}
67	          >
68	            {rotuloDoEscopo(aviso)}
69	          </Text>
