51	export function RankingsScreen({ inicial }: { inicial: Visao }) {
52	  const { colors } = useTheme();
53	  const insets = useSafeAreaInsets();
54	  const router = useRouter();
55	  const eu = useEu();
56	  const aluno =
57	    eu.data !== undefined &&
58	    eu.data.papeis.length === 1 &&
59	    eu.data.papeis[0] === "aluno";
60	  const perfil = usePerfil();
61	  const exAluno = aluno && (perfil.data?.exAluno ?? false);
62	  const visoes = visoesPara({ aluno, exAluno });
