66	    eu.data === undefined || visoes.includes(escolhida) ? escolhida : "geral";
67	  const [filtro, setFiltro] = useState<Filtro>("todos");
68	  const ranking = useRanking(visao, filtro === "seguidos");
69	
70	  const primeira = ranking.data?.pages[0];
