142	          onChange={setFiltro}
143	        />
144	      </View>
145	    </View>
146	  );
147	
148	  const vazio = ranking.isPending ? (
149	    <ActivityIndicator style={styles.espera} color={colors.ink2} />
150	  ) : ranking.isError ? (
