36	export const LIMITE_DO_COMENTARIO = 500;
37	
38	const caracteres = (texto: string) => Array.from(texto).length;
39	
40	// Os comentários de um post (produto.md 6.1), do mais antigo ao mais novo, como no
41	// Instagram, com o campo de comentar embaixo. Apagam o autor do comentário e a instituição;
42	// o dono do post não apaga comentário de terceiro. Sem prancheta: segue a identidade visual.
43	export function ComentariosScreen() {
44	  const { colors } = useTheme();
45	  const insets = useSafeAreaInsets();
46	  const router = useRouter();
47	  const { id } = useLocalSearchParams<{ id: string }>();
48	  const eu = useEu();
49	  const comentarios = useComentarios(id);
50	  const comentar = useComentar(id);
51	  const remover = useRemoverComentario(id);
