53	
54	  const papeis = eu.data?.papeis ?? [];
55	  const interage = papeis.includes("aluno") || papeis.includes("professor");
56	  const instituicao = papeis.includes("instituicao");
57	  const lista = comentarios.data?.pages.flatMap((pagina) => pagina.itens) ?? [];
58	  const longo = caracteres(texto) > LIMITE_DO_COMENTARIO;
59	  const naoExiste =
60	    comentarios.isError &&
61	    falhaParaTela(comentarios.error).codigo === "post-nao-encontrado";
62	
63	  const enviar = () =>
64	    comentar.mutate(texto, {
65	      onSuccess: () => {
66	        setTexto("");
67	        void comentarios.refetch();
68	      },
