73	    const acao = proprio ? "Apagar" : instituicao ? "Remover" : null;
74	    return (
75	      <View testID={`comentario-${item.id}`} style={styles.linha}>
76	        <Pressable
77	          role="link"
78	          accessibilityLabel={`Perfil de ${item.autor.nomeDeExibicao}`}
79	          onPress={() => router.push(perfilDe(item.autor.id, eu.data))}
80	        >
