134	            <ActivityIndicator style={styles.espera} color={colors.ink2} />
135	          ) : naoExiste ? (
136	            <EmptyState icon="message" title="Esse post não existe mais." />
137	          ) : comentarios.isError ? (
138	            <ErrorState
139	              message={falhaParaTela(comentarios.error).mensagem}
140	              onRetry={() => void comentarios.refetch()}
